// HEAT Service Worker — cache version: heat-cache-v4
// DO NOT EDIT THIS FILE DIRECTLY. Edit sw.template.js — the precache list
// is populated at build time by build.mjs from manifest.json.

const PRECACHE_URLS = [
  "/static/vendor/bootstrap.7f1d37f0d90b.min.css",
  "/static/vendor/bootstrap.aa53d582f97e.bundle.min.js",
  "/static/vendor/fontawesome.7954fe83f51c.min.css",
  "/static/vendor/admin-nav.f16329c57591.css"
];
const CACHE = "heat-cache-v4";

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE).then((cache) => cache.addAll(PRECACHE_URLS)).then(self.skipWaiting())
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(
        keys.filter((key) => key !== CACHE).map((key) => caches.delete(key))
      )
    ).then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", (event) => {
  const requestUrl = new URL(event.request.url);
  if (requestUrl.origin === location.origin) {
    event.respondWith(
      caches.match(event.request).then((cachedResponse) => {
        return cachedResponse || fetch(event.request);
      })
    );
  }
});
